import math

def calculate_E(a, b, c):
    # The simplified form is: E = sqrt(1001/c) + sqrt(1001/a) + sqrt(1001/b)
    try:
        term_a = math.sqrt(1001 / a)
        term_b = math.sqrt(1001 / b)
        term_c = math.sqrt(1001 / c)
        E = term_a + term_b + term_c
        return E
    except ZeroDivisionError:
        return None

def check_small_triples():
    solutions = []
    # Test triples where a, b, c are in {1, 2, 3, 4, 5}
    limit = 5
    for a in range(1, limit + 1):
        for b in range(1, limit + 1):
            for c in range(1, limit + 1):
                E = calculate_E(a, b, c)
                if E is not None:
                    # Check if E is very close to an integer
                    is_integer = abs(E - round(E)) < 1e-9
                    if is_integer:
                        solutions.append((a, b, c, round(E)))
    return solutions

solutions = check_small_triples()
print(solutions)
